(6385450, 946001, 26464, '<td valign="top">best in show 9</td>', 'best in show 9', '2011-04-13 18:28:31.000000', NULL, 1),
(6385462, 945458, 124982, '<td valign="top">I saw this image, and immediately thought of light trails from a car in the dark. This would''ve been awesome if you made it more punchier, perhaps by giving the road a nice deep orange cast instead of the brown. Anyway, that''s one of the first things that popped into my head, may work, may not. Anyway, love the S-curve you have going here!</td>', 'I saw this image, and immediately thought of light trails from a car in the dark. This would''ve been awesome if you made it more punchier, perhaps by giving the road a nice deep orange cast instead of the brown. Anyway, that''s one of the first things that popped into my head, may work, may not. Anyway, love the S-curve you have going here!', '2011-04-13 18:37:03.000000', NULL, 1),
(6385463, 946130, 124982, '<td valign="top">You definitely have the warm colors going, wish there was more detail in the object though.</td>', 'You definitely have the warm colors going, wish there was more detail in the object though.', '2011-04-13 18:38:15.000000', NULL, 1),
(6385467, 945899, 124982, '<td valign="top">Hmmm, tough one this. While the red throat is clearly a warm color, the rest of the green body is cold. This animal could fit into either of the challenges, warm or cool!<br/> <br/>That aside, I think the detail and definition in this is absolutely spectacular. Wish the whole face was in focus though, the nose is slightly out of focus which is distracting. A 7 from me nonetheless.</td>', 'Hmmm, tough one this. While the red throat is clearly a warm color, the rest of the green body is cold. This animal could fit into either of the challenges, warm or cool! That aside, I think the detail and definition in this is absolutely spectacular. Wish the whole face was in focus though, the nose is slightly out of focus which is distracting. A 7 from me nonetheless.', '2011-04-13 18:41:23.000000', NULL, 1),
(6385469, 945128, 124982, '<td valign="top">Quite beautiful.</td>', 'Quite beautiful.', '2011-04-13 18:42:29.000000', NULL, 1),
(6385473, 946111, 124982, '<td valign="top">WOW. This is waaaaaaaaaaaaay too overprocessed for an HDR. All sorts of haloing and artifacts in this one. Needs to be toned down considerably!</td>', 'WOW. This is waaaaaaaaaaaaay too overprocessed for an HDR. All sorts of haloing and artifacts in this one. Needs to be toned down considerably!', '2011-04-13 18:44:23.000000', NULL, 1),
(6385474, 945720, 124982, '<td valign="top">She looks much better in non-HDR! WOnderful lighting and tones!</td>', 'She looks much better in non-HDR! WOnderful lighting and tones!', '2011-04-13 18:45:29.000000', NULL, 1),
(6385477, 946064, 124982, '<td valign="top">I absolutely looooove Dobies! This is one gorgeous dog, hope to see more of him/her!<br/> <br/>Only critique about the image...way too much distracting background. A tighter crop on the dog would''ve been ideal!</td>', 'I absolutely looooove Dobies! This is one gorgeous dog, hope to see more of him/her! Only critique about the image...way too much distracting background. A tighter crop on the dog would''ve been ideal!', '2011-04-13 18:47:21.000000', NULL, 1),
